  \`);
  const signups = [], logins = [], connections = [], mcp = [], errorSamples = [], warningSamples = [];
  let errors = 0, warnings = 0, logsUrl = null;
  for (const row of rows) {
    const text = String(row.payload_text ?? "").trim();
    if (row.connection_slug === "lobu-product-activity-db") {
      if (row.title === "New signup" && text) signups.push(text);
      if (row.title === "User login" && text) logins.push(text);
      if (row.title === "New connection" && text) connections.push(text);
      if (row.title === "MCP activity" && text) mcp.push(text);
