      errors += Number(meta.errors ?? 0);
      warnings += Number(meta.warnings ?? 0);
      errorSamples.push(...(Array.isArray(meta.error_samples) ? meta.error_samples : []));
      warningSamples.push(...(Array.isArray(meta.warning_samples) ? meta.warning_samples : []));
      if (row.source_url) logsUrl = row.source_url;
    }
  }
  if (!(signups.length || logins.length || connections.length || mcp.length || errors || warnings)) {
