  const safe = (value) => String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
  const section = (heading, values) => values.length ? [
    { type: "divider" },
    { type: "text", content: \`**\${heading} (\${values.length})**\\n\${values.map((value) => \`• \${safe(value)}\`).join("\\n")}\` }
  ] : [];
  const children = [{
    type: "fields",
