      { type: "field", label: "Signups", value: String(signups.length) },
      { type: "field", label: "Login sessions", value: String(logins.length) },
      { type: "field", label: "Online users", value: String(online.length) },
      { type: "field", label: "New connections", value: String(connections.length) },
      { type: "field", label: "Active MCP conversations", value: String(mcp.length) },
      { type: "field", label: "Errors / warnings", value: \`\${errors} / \${warnings}\` }
    ]
  },
  ...section("New signups", signups),
  ...section("Online users", online),
  ...section("New connections", connections),
  ...section("Active MCP conversations", mcp),
  ...section("Recent errors", [...new Set(errorSamples)]),
  ...section("Recent warnings", [...new Set(warningSamples)])];
  if (logsUrl) children.push({ type: "actions", children: [{ type: "link-button", url: logsUrl, label: "Open production logs" }] });
